const fs = require('fs/promises');
const fsSync = require('fs');
const path = require('path');
const env = require('../config/env');

// Evidence files live on the server disk, outside any public folder:
//   <UPLOAD_DIR>/tmp/<uuid>                         while the request is processed
//   <UPLOAD_DIR>/reports/<report_id>/<uuid>.<ext>   once the report is saved
// Names are generated by the server; the original file name is never used.
// Files are only served through an authenticated endpoint that checks the owner.

const uploadRoot = path.resolve(env.UPLOAD_DIR);
const tmpDir = path.join(uploadRoot, 'tmp');

function ensureTmpDir() {
  fsSync.mkdirSync(tmpDir, { recursive: true });
  return tmpDir;
}

/** Moves a temporary upload into the report folder. Returns the path relative to UPLOAD_DIR. */
async function moveToReport(tmpPath, reportId, fileName) {
  const relative = path.join('reports', reportId, fileName);
  const target = resolveStored(relative);
  await fs.mkdir(path.dirname(target), { recursive: true });
  await fs.rename(tmpPath, target);
  return relative.split(path.sep).join('/');
}

/** Absolute path of a stored file; refuses paths that escape UPLOAD_DIR. */
function resolveStored(relativePath) {
  const absolute = path.resolve(uploadRoot, relativePath);
  if (!absolute.startsWith(uploadRoot + path.sep)) {
    throw new Error('Ruta de archivo fuera de la carpeta de subidas');
  }
  return absolute;
}

/** Deletes files, ignoring the ones that no longer exist. */
async function removeFiles(paths) {
  await Promise.all(paths.filter(Boolean).map((p) => fs.rm(p, { force: true })));
}

module.exports = { uploadRoot, ensureTmpDir, moveToReport, resolveStored, removeFiles };
